{
  "status": "Working notes. Include a trial in measured results only when its complete paired matrix and oracle exist. Decisions may change after combined verification.",
  "trials": [
    {
      "trial": 32,
      "title": "Stable generic-object routing",
      "hypothesis": "Cache repeated class dispatch only for providers that promise stable class information.",
      "decision": "Rejected: small/Blueprint/table regressions outweighed modest level gains."
    },
    {
      "trial": 33,
      "title": "Fuse replay construction and value decoding",
      "hypothesis": "Validate all headers, then construct and decode each record in one walk.",
      "decision": "Rejected: decoding a temporary record increased copies and slowed tables."
    },
    {
      "trial": 34,
      "title": "Prepare common scalar decisions",
      "hypothesis": "Attach scalar decoding plans to each validated layout, alongside temporary-record fusion.",
      "decision": "Rejected: planning did not offset the temporary-record cost."
    },
    {
      "trial": 35,
      "title": "Validate common leaf headers with fixed words",
      "hypothesis": "Compare all 24 stable leaf-header bytes and the current bool flag using safe integer loads.",
      "decision": "Retained as the common leaf-header validator in core1."
    },
    {
      "trial": 37,
      "title": "Decode in the final vector slot",
      "hypothesis": "Push the record before decoding so its value is written in its final location.",
      "decision": "Retained final-slot decoding as part of core1; not a useful independent winner."
    },
    {
      "trial": 38,
      "title": "Compact privately owned object paths",
      "hypothesis": "Use Box<str> inside the private ObjectPath representation while preserving its public methods.",
      "decision": "Not retained in core1: compatible private representation, but broader combinations regressed cold/level lanes."
    },
    {
      "trial": 39,
      "title": "Prepare scalars with separate construction and decoding walks",
      "hypothesis": "Keep ordinary two-pass ownership while reusing scalar plans.",
      "decision": "Not retained alone: weak aggregate benefit."
    },
    {
      "trial": 41,
      "title": "Cache complete struct-resolution facts",
      "hypothesis": "Memoize pure qualified-struct facts within one decode session.",
      "decision": "Rejected: small-package overhead and hashing/cloning costs."
    },
    {
      "trial": 42,
      "title": "Store fewer redundant header ranges",
      "hypothesis": "Recover expected header bytes from the parent source slice.",
      "decision": "Rejected: extra lookup/bounds work slowed tables."
    },
    {
      "trial": 44,
      "title": "Decode UTF-16 directly from bytes",
      "hypothesis": "Avoid the intermediate u16 vector; retain old malformed-input diagnostics.",
      "decision": "Rejected: no broad throughput gain."
    },
    {
      "trial": 45,
      "title": "Build binary math breadcrumbs lazily",
      "hypothesis": "Delay formatting math error paths until an error needs them.",
      "decision": "Rejected: broader regressions despite a plausible allocation saving."
    },
    {
      "trial": 46,
      "title": "Read vector/rotator components as one block",
      "hypothesis": "Validate a complete math value once, preserving ordinary truncation diagnostics.",
      "decision": "Rejected: no broad gain in the generic helper."
    },
    {
      "trial": 49,
      "title": "Use compact struct-fact cache keys",
      "hypothesis": "Key pure facts by identity and module names instead of cloning/hashing a complete type tree.",
      "decision": "Rejected: cold workloads still regressed."
    },
    {
      "trial": 50,
      "title": "Use a small linear struct-fact cache",
      "hypothesis": "Replace hashing with a bounded contiguous scan.",
      "decision": "Not retained: warm level gain with consistent cold-package regressions."
    },
    {
      "trial": 51,
      "title": "Share immutable type-parameter slices",
      "hypothesis": "Reduce repeated metadata cloning using Arc-backed slices.",
      "decision": "Rejected: cold regressions and a public Rust field-type change."
    },
    {
      "trial": 52,
      "title": "Use thin shared pointers to parameter vectors",
      "hypothesis": "Shrink type nodes further using Arc<Vec<...>>.",
      "decision": "Rejected: severe table slowdown and a public API change."
    },
    {
      "trial": 53,
      "title": "Combine compact paths and header words",
      "hypothesis": "Test the combined result rather than adding independent percentages.",
      "decision": "Not retained: table/corpus gains with level and Blueprint regressions."
    },
    {
      "trial": 54,
      "title": "Prepare vector/rotator recipes per layout",
      "hypothesis": "Resolve math identity once and decode exact-width values from validated layouts.",
      "decision": "Retained math recipes in the combined core1 implementation;24192 guard/bit cases passed."
    },
    {
      "trial": 55,
      "title": "Allocate single-child shared metadata directly",
      "hypothesis": "Avoid an intermediate vector for the overwhelmingly common one-child case.",
      "decision": "Rejected for production: public API change and cold-workload regressions."
    },
    {
      "trial": 56,
      "title": "Use a thin shared single-child node",
      "hypothesis": "Store one child directly behind an Arc; use a vector for longer lists.",
      "decision": "Rejected: severe table slowdown, public API change."
    },
    {
      "trial": 57,
      "title": "Borrow invariant decode context",
      "hypothesis": "Pass a small depth-plus-root-reference value through recursion.",
      "decision": "Rejected alone: smaller arguments did not reliably improve elapsed time."
    },
    {
      "trial": 58,
      "title": "Combine compact context and struct facts",
      "hypothesis": "Reduce argument size while retaining the bounded fact cache.",
      "decision": "Not retained: level gains with Blueprint/small regressions."
    },
    {
      "trial": 59,
      "title": "Carry a GUID predicate in private type specs",
      "hypothesis": "Store the only needed nonzero-GUID fact rather than copying Option<Guid>.",
      "decision": "Not retained alone: no reliable broad gain. Expanded codec oracle passed."
    },
    {
      "trial": 60,
      "title": "Borrow temporary container type names",
      "hypothesis": "Avoid owning a String used only during array/set/map decoding.",
      "decision": "Retained borrowed temporary container names in core1."
    },
    {
      "trial": 61,
      "title": "Resolve struct identity and module once",
      "hypothesis": "Build all pure facts from one name/module resolution instead of repeated helper lookups.",
      "decision": "Retained single-pass struct facts in core1; frozen helper equivalence cases passed."
    },
    {
      "trial": 62,
      "title": "Combine small scope and small type spec",
      "hypothesis": "Test argument-size reductions together.",
      "decision": "Rejected: consistent corpus and level regressions."
    },
    {
      "trial": 63,
      "title": "Combine borrowed names and one-pass struct facts",
      "hypothesis": "Remove repeated ownership and identity-resolution work together.",
      "decision": "Retained its two ownership/resolution components in core1."
    },
    {
      "trial": 64,
      "title": "Use prepared math with separate value walk",
      "hypothesis": "Isolate planning from fused final-slot construction.",
      "decision": "Provisional: consistent level gain, table/cold effects mixed."
    },
    {
      "trial": 65,
      "title": "Add a direct guarded math-record path",
      "hypothesis": "Skip reader/path setup for fully available qualified 24-byte vectors and rotators.",
      "decision": "Not preferred alone: modest benefit compared with prepared-layout decoding."
    },
    {
      "trial": 66,
      "title": "Remove atomic reference counting from shared slices",
      "hypothesis": "Diagnostic Rc variant to explore sharing costs.",
      "decision": "Rejected for production: changes public types and Send/Sync, cold regressions."
    },
    {
      "trial": 67,
      "title": "Remove atomics from thin single-child nodes",
      "hypothesis": "Diagnostic Rc version of the thin-node representation.",
      "decision": "Rejected: severe table slowdown persists; breaks public types and Send/Sync."
    },
    {
      "trial": 68,
      "title": "Borrow the initial native ancestry path",
      "hypothesis": "An ancestry check needs to read the class path, not clone its owned storage.",
      "decision": "Retained borrowing of the initial native ancestry path in core1."
    },
    {
      "trial": 69,
      "title": "Borrow generated-class parent paths too",
      "hypothesis": "Read parent object paths from package tables during ancestry traversal.",
      "decision": "Not retained alone: table regression despite corpus/level gains."
    },
    {
      "trial": 70,
      "title": "Borrow reference-validation inputs",
      "hypothesis": "Avoid allocating display strings solely to check reference validity.",
      "decision": "Awaiting final selection based on measured effects."
    },
    {
      "trial": 71,
      "title": "Borrow read-only name comparisons broadly",
      "hypothesis": "Use Cow resolution in private comparisons and validation sites.",
      "decision": "Not retained alone: weak aggregate gain and small-package regression."
    },
    {
      "trial": 72,
      "title": "Prepare name, enum, string and math leaves",
      "hypothesis": "Reuse validated type interpretation; ordinary decoding owns every unsuccessful probe diagnostic.",
      "decision": "Retained prepared Name/Enum/String/math leaves and final-slot writes in core1."
    },
    {
      "trial": 73,
      "title": "Use all leaf plans with a separate value walk",
      "hypothesis": "Check whether separate construction and decoding is preferable with more leaf kinds.",
      "decision": "Not preferred: less gain than final-slot fusion."
    },
    {
      "trial": 74,
      "title": "Normalize private type dispatch to an enum",
      "hypothesis": "Replace repeated private string comparisons with compact type kinds.",
      "decision": "Rejected: normalization work did not pay off on this configuration."
    },
    {
      "trial": 75,
      "title": "Combine enum dispatch and borrowed context",
      "hypothesis": "Test both compact representations together.",
      "decision": "Rejected: no reliable broad gain."
    },
    {
      "trial": 84,
      "title": "Recycle metadata after a streaming callback",
      "hypothesis": "Add a visitor that retains reusable metadata while values remain freshly decoded.",
      "decision": "Provisional/rejected first design: old owned callers and cold packages regressed."
    },
    {
      "trial": 85,
      "title": "Use recycled callbacks in streaming JSON",
      "hypothesis": "Connect the first visitor design to the existing streaming inspection API.",
      "decision": "Provisional: JSON gains with ownership-path tradeoffs."
    },
    {
      "trial": 86,
      "title": "Replay rows with changing payload widths",
      "hypothesis": "Check all stable header fields while reading each current payload size.",
      "decision": "Retained the DataTable variable-width technique in the combined core1 implementation."
    },
    {
      "trial": 87,
      "title": "Use variable-width replay for object streams too",
      "hypothesis": "Generalize variable payload validation beyond table rows.",
      "decision": "Rejected alone: normal corpus and level regressions."
    },
    {
      "trial": 88,
      "title": "Keep several recent table layouts",
      "hypothesis": "Use four MRU layouts and disable unsuccessful learning after repeated misses.",
      "decision": "Retained bounded adaptive row-layout learning in core1."
    },
    {
      "trial": 89,
      "title": "Combine adaptive layouts and variable widths",
      "hypothesis": "Cover both changing property order/default omission and changing payload sizes.",
      "decision": "Provisional: strong synthetic gains, validate final combined source."
    },
    {
      "trial": 90,
      "title": "Separate visitor storage and stable generic routing",
      "hypothesis": "Keep the original owned cache layout and decode body while adding an opt-in streaming cache.",
      "decision": "Experimental only, not retained: old owned API cost, plus missing ordinary native postprocessing hooks identified after measurement. Current456case parity does not establish general equivalence."
    },
    {
      "trial": 91,
      "title": "Use the separate visitor in streaming JSON",
      "hypothesis": "Measure the consumer-facing result of the second visitor design.",
      "decision": "Experimental only, not retained: same incomplete generic-object prototype plus JSON integration; later102/103 restore the missing hooks."
    },
    {
      "trial": 92,
      "title": "Validate variable object/row layouts before allocation",
      "hypothesis": "Perform a complete metadata-free validation pass before constructing records.",
      "decision": "Rejected: two-pass validation still regressed ordinary corpus, level and table."
    },
    {
      "trial": 93,
      "title": "Use two-pass variable validation only for rows",
      "hypothesis": "Keep the generic object path unchanged.",
      "decision": "Not preferred: width stress wins but slower ordinary table than the one-pass version."
    },
    {
      "trial": 94,
      "title": "Bulk decode vector/rotator arrays",
      "hypothesis": "Prove the complete fixed-width array bytes exist, then decode without per-element paths and dispatch.",
      "decision": "Rejected: no ordinary corpus/level gain; no production adoption."
    },
    {
      "trial": 95,
      "title": "Bulk decode additional core struct arrays",
      "hypothesis": "Extend the safe complete-block kernel to IntPoint, Color and LinearColor.",
      "decision": "Rejected: ordinary corpus/level regressions; no production adoption."
    },
    {
      "trial": 96,
      "title": "Combine source candidates",
      "hypothesis": "Borrowed names, one-pass facts, prepared leaves, header words and borrowed ancestry paths.",
      "decision": "Not preferred: strong table gains with cold-package regressions; generalized97 selected."
    },
    {
      "trial": 97,
      "title": "Combine source candidates with adaptive variable rows",
      "hypothesis": "Integrate variable payloads and several row layouts with prepared leaf callbacks.",
      "decision": "Retained generalized row replay and other components through lazy-plan version112/core1."
    },
    {
      "trial": 98,
      "title": "Combine source candidates with two-pass variable rows",
      "hypothesis": "Use one row layout and allocation-free validation on misses.",
      "decision": "Not retained: cold regressions and narrower/worse variable-width behavior than97."
    },
    {
      "trial": 99,
      "title": "Nested replay census",
      "hypothesis": "Measure optional cross-export nested-header reuse; array-local reuse is rare.",
      "decision": "Prepared diagnostic only, not run; no throughput claim."
    },
    {
      "trial": 100,
      "title": "Share nested tag layouts across exports",
      "hypothesis": "Cache nested metadata per package session, retain owned output and fresh values.",
      "decision": "Prepared, not run."
    },
    {
      "trial": 102,
      "title": "Use a separate callback session",
      "hypothesis": "Preserve the exact old owned-session layout and drop path while offering opt-in recycling.",
      "decision": "Prepared, not run."
    },
    {
      "trial": 103,
      "title": "Separate callback session for streaming JSON",
      "hypothesis": "Consume recycled models through the existing JSON output without enlarging owned sessions.",
      "decision": "Prepared, not run."
    },
    {
      "trial": 106,
      "title": "Validate more fixed header widths",
      "hypothesis": "Specialize common container headers with safe constant-size word comparisons.",
      "decision": "Prepared, not run."
    },
    {
      "trial": 107,
      "title": "Add more header widths to the core candidate",
      "hypothesis": "Test the new validator in combination; direct reference is trial96.",
      "decision": "Prepared, not run."
    },
    {
      "trial": 112,
      "title": "Prepare semantic plans only on reuse",
      "hypothesis": "Avoid preparing recipes for captured layouts that never match again; reference is trial97.",
      "decision": "Selected as formatted core1.714UAssetRust tests,8ignored;Clippy/Windows/Node24+26originalWASM/207084wire pass. Full portable check still ENOTDIR optionalWindows package;freshUE5.7/5.8 unavailable."
    },
    {
      "trial": 113,
      "title": "Keep cached tags compact",
      "hypothesis": "Use checked u16 offsets within the existing16KiB optional header budget; reference is trial97.",
      "decision": "Not retained: no consistent broad gain; cold Blueprint regression."
    },
    {
      "trial": 114,
      "title": "Combine lazy preparation and compact tags",
      "hypothesis": "Test both changes together against trial97.",
      "decision": "Not retained: direct118comparison with112 failed to improve corpus/table; keep simpler112."
    },
    {
      "trial": 115,
      "title": "Validate fixed and variable headers with safe words",
      "hypothesis": "Remove more small memcmp calls; comparison reference is trial97.",
      "decision": "Prepared, not run."
    },
    {
      "trial": 116,
      "title": "Specialize only variable header prefixes",
