      "decision": "Prepared, not run."
    },
    {
      "trial": 117,
      "title": "Use a safe Latin1 conversion library",
      "hypothesis": "Avoid the second ASCII validation while preserving every8-bit code unit; dependency-only control planned.",
      "decision": "Prepared, dependency not fetched or tested."
    },
    {
      "trial": 118,
      "title": "Direct compact-tag confirmation",
      "hypothesis": "Compare114directly with112 before selection; no new source variant.",
      "decision": "Reject compact addition;112 selected."
    },
    {
      "trial": 121,
      "title": "Hash-index the immutable default schema model",
      "hypothesis": "Replace repeated linear scans only for the exact built-in immutable model; custom models keep scans.",
