      "decision": "Prepared, not run."
    },
    {
      "trial": 125,
      "title": "Census sparse GUID metadata",
      "hypothesis": "Count present GUIDs and actual record sizes before a compact-record prototype.",
      "decision": "Prepared diagnostic, not run; no speed claim."
    }
  ]
}

